/// `NPC.OnGameEventClearedForTheFirstTime` case 16/17/18
/// (`NPC.cs:78780-78788`): when a mech boss falls and ALL THREE are downed
/// in hardmode, `WorldGen.GeneratePlanteraBulbOnAllMechsDefeated`
/// (`WorldGen.cs:74127-74186`) forces a Plantera bulb into the jungle.
/// The C# gates on `Main.netMode != 1` (the port runs the host path) and
/// draws on `genRand` (the `UpdateNPCs` swap — `checkDead` runs inside
/// `NPC.UpdateNPC`, `Main.cs:17767-17769`). W4-c31 jungle residuals.
fn try_plantera_bulb_on_mech_clear(app: &mut App) {
    let w = &app.world;
    if w.hard_mode && w.downed_mech_boss1 && w.downed_mech_boss2 && w.downed_mech_boss3 {
        let dungeon_x = w.dungeon_x;
        tr_core::growth::generate_plantera_bulb_on_all_mechs_defeated(
            &mut app.world,
            dungeon_x,
            app.rngs.stream(RngKey::UpdateNpcs),
        );
    }
}

/// W4-d125 — the `Npc::integrate_flyer_collision` body as a module helper
/// (the union merge kept it private in `npc.rs`, so the branch's
/// `integrate_flyer_collision_pub` wrapper is unavailable). Verbatim.
fn integrate_flyer_collision_pub(npc: &mut Npc, world: &World) {
    let (w, h) = npc.size();
    npc.old_vx = npc.vx;
    npc.old_vy = npc.vy;
    let slow = if npc.wet { 0.5 } else { 1.0 };
    let nx = npc.x + npc.vx * slow;
    npc.collide_x = crate::player::collides_rect(world, nx, npc.y, w, h);
    if npc.collide_x {
        npc.vx = 0.0;
    } else {
        npc.x = nx;
    }
    let ny = npc.y + npc.vy * slow;
    npc.collide_y = crate::player::collides_rect(world, npc.x, ny, w, h);
    if npc.collide_y {
        if npc.vy > 0.0 {
            let ty = ((ny + h) / TILE_PX).floor() as i32;
            npc.y = ty as f32 * TILE_PX - h;
            npc.on_ground = true;
        } else if npc.vy < 0.0 {
            let ty = (ny / TILE_PX).floor() as i32;
            npc.y = (ty + 1) as f32 * TILE_PX;
        }
        npc.vy = 0.0;
    } else {
        npc.y = ny;
        npc.on_ground = false;
    }
}

/// W4-d31 — the `style83_movement_tail` body (dropped from `npc.rs` by the
/// union merge): the pooled style-83 step's post-`AI` integration, verbatim.
fn style83_movement_tail(npc: &mut Npc, world: &World) {
    // `:90473-90476` — the dead-band X snap (double compare), both kinds.
    if (npc.vx as f64) < 0.005 && (npc.vx as f64) > -0.005 {
        npc.vx = 0.0;
    }
    if npc.kind.cs_id() == 437 {
        // `:90496-90498` — the stamps + the raw integration.
        npc.old_x = npc.x;
        npc.old_y = npc.y;
        npc.old_direction = npc.facing;
        npc.integrate_no_tile_collide();
        return;
    }
    // The devotee: gravity + the fall cap (`:90465-90472`).
    npc.vy = (npc.vy + crate::npc::GRAVITY).min(crate::npc::MAX_FALL);
    let (w, h) = npc.size();
    // `UpdateCollision`'s axis integration (the zombie stand-in shape,
    // `NPC.cs:92523-92608`): the blocked X axis zeroes the velocity,
    // the blocked Y axis snaps to the floor/ceiling.
    let nx = npc.x + npc.vx;
    if !crate::player::collides_rect(world, nx, npc.y, w, h) {
        npc.x = nx;
    } else {
        npc.vx = 0.0;
    }
    let ny = npc.y + npc.vy;
    if !crate::player::collides_rect(world, npc.x, ny, w, h) {
        npc.y = ny;
        npc.on_ground = false;
    } else if npc.vy > 0.0 {
        let ty = ((ny + h) / TILE_PX).floor() as i32;
        npc.y = ty as f32 * TILE_PX - h;
        npc.vy = 0.0;
        npc.on_ground = true;
    } else if npc.vy < 0.0 {
        let ty = (ny / TILE_PX).floor() as i32;
        npc.y = (ty + 1) as f32 * TILE_PX;
        npc.vy = 0.0;
    }
}

/// The player's death message: a DoT drain death resolves its attribution's
/// `DeathText.*` row family (`KillMe(PlayerDeathReason.ByOther(N))` with the
/// `Lang.cs:1045-1127` variant roll — the C# rides `Main.rand`; the port
/// draws it from the `UpdatePlayers` stream (the death runs in
/// `Player.KillMe` under the `UpdatePlayers` swap)); every other death is
/// the `DeathText.Slain` row. The single-variant rows (`Poisoned`, `Slain`,
/// `Spored`) carry no `_N` suffix — the C# switch draws NOTHING for them
/// (`Lang.cs:1069`/`:1084`/`:1126`), so the port skips the draw too.
fn dot_death_text(pending: Option<DotDeath>, player_name: &str, rng: &mut UnifiedRandom) -> String {
    match pending {
        Some(death) => {
            // `Main.rand.Next(variants) + 1` (`Lang.cs:1057-1127`) — only
            // the multi-variant families roll.
            let (_, variants) = crate::death::death_text_key(death);
            let variant = if variants <= 1 {
                1
            } else {
                rng.next_max(variants as i32) + 1
            };
            crate::death::death_message(death, variant, player_name)
        }
        None => crate::death::slain_message(player_name),
    }
}

/// `Player.StatusFromNPC` (`Player.cs:22333`), the black-slime row `:22591`:
/// `npc.type == 1 && npc.netID == -6` rolls `Next(4) == 0` for 900 ticks of
/// Darkness on touch. The roll rides the `UpdateNPCs` stream — the C#
/// `StatusFromNPC` runs inside `NPC.UpdateNPC` under the `UpdateNPCs` swap.
pub(crate) fn black_slime_darkness_touch(
    slime: &Npc,
    player: &mut crate::player::Player,
    rng: &mut UnifiedRandom,
) {
    // `StatusFromNPC`'s `Main.rand.Next(4) == 0` (`Player.cs:22591`), under
    // the `UpdateNPCs` swap (the touch runs inside `NPC.Update`).
    if slime.kind == NpcKind::Slime
        && slime.slime == SlimeVariant::Black
        && slime.touches(player)
        && rng.next_max(4) == 0
    {
        player.buffs.add_buff(22, 900);
    }
}

/// `AI_006_Worms` (`NPC.cs:50963-52090`) — the chain pass. The vanilla runs
/// it inside each NPC's `Update` against the `Main.npc` slots; the port runs
/// it here against the `Vec` (the slot order = the Vec order = the spawn
/// order, so the head moves before its followers exactly like the original).
/// The head digs (`flag3`'s solid-overlap scan switches the direct aim), the
/// followers ride the rigid trail (`:51867-51922`), a missing leader kills
/// the link (the chain death, `:51425-51433`). The EoW middle-segment split
/// (`:51511-51518`'s `Transform`) is deferred: a middle kill takes the tail
/// with it (the chain-death rule), the split lands with the boss-summon
/// work.
/// The town shop open (`NPC.cs`'s right-click dialog → `OpenShop`): the
/// press-edge cursor on a town NPC's rect opens the MERCHANT's shop (the
/// Guide offers none — M4-TOWN-3's finding). The stock and the happiness
/// multiplier capture at the open (`Main.OpenShop`'s `SetupShop` +
/// `ShopHelper.OpenShop` pair).
/// `Player.taxRate` (`Player.cs:57097`): 3600 ticks between collections.
pub(crate) const TAX_RATE: i32 = 3600;
/// `Player.CollectTaxes`'s cap — `Item.buyPrice(0, 25)` = 25 gold
/// (`Player.cs:24132`/`:24151`).
pub(crate) const TAX_CAP: i32 = 250_000;

/// `Main.NPCChatText_DoTaxCollector` (`Main.cs:40180-40225`): the Tax
/// Collector's right-click pays the accrued tax purse out in coins — the
/// platinum→gold→silver→copper split at the PLAYER's centre
/// (`Main.LocalPlayer.Center`, `:40192`/`:40199`/`:40206`/`:40215`), then
/// the purse empties. The happiness adjustment DIVIDES the payout
/// (`:40184`: `(int)((float)taxMoney / currentShoppingSettings.
/// PriceAdjustment)`) — the TALK-OPEN LATCH (`Player.cs:4389`), the same
/// value `GetCoinValueText_TaxCollector` displays (`:39933`, the <0→0
/// clamp there is display-only). A happy collector (adjustment < 1) pays
/// MORE than the accrued purse; an unhappy one pays less. His roster rows
/// are live: the biome table (`PersonalityDatabasePopulator.cs:47-51`,
/// Like Snow / Dislike Hallow) + the neighbor switch
/// (`AllPersonalitiesModifier.cs:321-342`, Merchant love / PartyGirl like /
/// Demolitionist + Mechanic dislike / Santa hate). The paid arm answers
/// `Lang.dialog(Main.rand.Next(380, 384))` (`:40217`) AFTER the coin
/// split, BEFORE the purse zero (`:40218`); the empty purse answers
/// `Next(390, 401)` (`:40222`). Both draws ride the bare-`Main.rand`
/// stand-in — the click runs outside every swap (S1-A-11 §4). The
/// portrait hop (`:40224`) is g58's. (batch-L: g58's latch-divide +
/// player-centre body per research/68 §4 — f37's plain-1.0 twin
/// superseded — with f37's dialog-tail census kept.)
pub(crate) fn tax_collector_payout(app: &mut App, npc_idx: usize) -> bool {
    // `Main.DoNPCPortraitHop` (`Main.cs:40224` — the tail of BOTH the
    // purse>0 and the empty-purse arms).
    crate::ui::npc_chat::do_npc_portrait_hop(app);
    if app.world.tax_money <= 0 {
        // `:40220-40223` — the empty-purse refusal: one of the eleven
        // "come back later" lines.
        let roll = app.rngs.global().next_range(390, 401);
        app.npc_chat_text = crate::lang::dialog(roll);
        return true;
    }
    // `:40184` — the latched-adjustment divide (float divide, int trunc).
    let mut num =
        (app.world.tax_money as f32 / app.shopping_settings.price_adjustment) as i32;
    // The spawn origin: `Main.LocalPlayer.Center` (`:40192`), NOT the
    // collector's box — the headless no-player tests fall back to his
    // centre (the vanilla always has a local player).
    let (px, py) = app
        .player
        .as_ref()
        .map(|p| p.center())
        .unwrap_or_else(|| app.npcs[npc_idx].center());
    while num > 0 {
        let (kind, stack) = if num > 1_000_000 {
            let stack = num / 1_000_000;
            num -= 1_000_000 * stack;
            (74u16, stack as u32)
        } else if num > 10_000 {
            let stack = num / 10_000;
            num -= 10_000 * stack;
            (73, stack as u32)
        } else if num > 100 {
            let stack = num / 100;
            num -= 100 * stack;
            (72, stack as u32)
        } else {
            let stack = num.max(1);
            num -= stack;
            (71, stack as u32)
        };
        // The payout is a right-click interaction — `Player.ItemCheck` under
        // the `UpdatePlayers` swap; the coin spawn draws ride the same
        // stream as the turn-in's (`Item.NewItem`'s `Main.rand`).
        let rng = app.rngs.stream(RngKey::UpdatePlayers);
        crate::world_sim::items::spawn_item_drop_px(
            &mut app.items,
            rng,
            kind,
            stack,
            Vec2::new(px, py),
        );
    }
    // `:40217` — the paid line draws AFTER the split, BEFORE the zero.
    let roll = app.rngs.global().next_range(380, 384);
    app.npc_chat_text = crate::lang::dialog(roll);
    app.world.tax_money = 0;
    true
}

/// `TileReachCheckSettings.Simple.GetWorldRegion`
/// (`TileReachCheckSettings.cs:76-89`): the player's tile box —
/// `LX = (int)(position.X / 16f) - x` … `HX = (int)Ceiling((position.X +
/// width) / 16f) - 1 + x` with `x = Player.tileRangeX * multiplier` capped
/// by the 20-tile `TileReachLimit` (`:11-22`) — converted back to pixels
/// with the `HX += 15` / `HY += 15` corrections (`:68-69`). `Simple` is
/// `TileRangeMultiplier = 1`, `TileReachLimit = 20` (`:83-87`), and
/// `Player.DefaultTileRangeX/Y = 5/3` (`Player.cs:57113-57114`).
///
/// Returns `(LX, LY, HX, HY)` in world pixels.
pub(crate) fn chat_world_region(p: &crate::player::Player) -> (f32, f32, f32, f32) {
    let lx = ((p.x / 16.0) as i32 - 5) as f32 * 16.0;
    let ly = ((p.y / 16.0) as i32 - 3) as f32 * 16.0;
    let hx = (((p.x + crate::player::WIDTH) / 16.0).ceil() as i32 - 1 + 5) as f32 * 16.0 + 15.0;
    let hy = (((p.y + crate::player::HEIGHT) / 16.0).ceil() as i32 - 1 + 3) as f32 * 16.0 + 15.0;
    (lx, ly, hx, hy)
}

/// The right-click talk action (`Main.cs:42993-43083`) — the live route to
/// [`crate::npc_chat::get_chat`].
///
/// **The close rule** (`Player.cs:27494-27503`) runs every tick: while
/// `talkNPC >= 0`, the world region no longer intersecting the NPC's box, a
/// chest being open, or the NPC gone clears the latch (`SetTalkNPC(-1)`,
/// `Main.npcChatText = ""`) with sound 11 unless the chest path took it.
///
/// **The open arm** fires on the fresh right-press edge — the C# gate
/// `Main.mouseRight && Main.npcChatRelease` (`Main.cs:43070`) with
/// `npcChatRelease` the inverted `mouseRight` latch of
/// `DrawInterface_41_InterfaceLogic4` (`Main.cs:45000-45009`) — for the
/// first live `townNPC` under the world region (`:43047`'s
/// `worldRegion.Intersects(nPC box)`, the `!player.dead` gate at `:43068`)
/// that is not already latched (`:43077`'s `player.talkNPC != i`). It latches
/// `SetTalkNPC(i)` (`:43081`) and answers `GetChat()` (`:43082`).
///
/// The RNG rides [`crate::app::NamedRngs::global`] — the C#'s `Main.rand`
/// draws `GetChat` outside every `Main.SwapRandom` stage, so the bare-Main.rand
/// stand-in stream is the named stream (the S1-A-10 contract).
///
/// `Some(text)` consumes the right-click press; `None` falls through to the
/// chest/tile routes — and to the collapsed shop arms, which stay reachable
/// through the same-NPC re-click (`talkNPC == i` declines here).
pub fn talk_to_npc(app: &mut App, prev_place_down: bool) -> Option<String> {
    // The per-tick close (`Player.cs:27494-27503`).
    if let Some(i) = app.talk_npc {
        let region = app
            .player
            .as_ref()
            .map(chat_world_region)
            .unwrap_or((0.0, 0.0, 0.0, 0.0));
        let (lx, ly, hx, hy) = region;
        let inside = app.npcs.get(i).is_some_and(|n| {
            n.hp > 0 && {
                let (w, h) = n.size();
                n.x < hx && n.x + w > lx && n.y < hy && n.y + h > ly
            }
        });
        if !inside || app.open_container() != -1 {
            if app.open_container() == -1 {
                crate::chest::play_menu_sound(app, 11);
            }
            app.set_talk_npc(None); // `SetTalkNPC(-1)` — the settings reset rides it
            app.npc_chat_text.clear();
            // `Player.SetTalkNPC(-1)` (`Player.cs:4383-4386`):
            // `currentShoppingSettings = NotInShop` — the mood latch resets
            // to 1.0 (W4-f37; the shop-open latch rides the same field).
            app.shop_mood = 1.0;
            // W4-f30 — the Joja latches clear on the close (`NPC.cs:93772`).
            crate::dryad_stardew::reset_joja_latches(app);
        }
    }
    // The open arm's gates: a fresh press, no inventory panel over the world.
    if !app.place_down || prev_place_down || app.inventory_open {
        return None;
    }
    let Some(p) = app.player.as_ref() else {
        return None;
    };
    if p.hp <= 0 {
        return None; // `:43068` — `flag3 && !player.dead`
    }
    let region = chat_world_region(p);
    // `Main.cs:43017` — `flag2 = mouse-over || (SmartInteractShowingGenuine
    // && SmartInteractNPC == i)`; `:43048-43052` — `flag3` starts from the
    // smart-interact pick and the town-NPC-in-region test ORs in. The
    // smart-cursor NPC pick (the NPC provider's win, W4-g86) lets the talk
    // arm reach an NPC the mouse is NOT directly over — the first such
    // NPC in slot order, exactly the C#'s per-NPC loop order.
    let smart_pick = if app.smart_interact.showing_genuine && app.smart_interact.npc >= 0 {
        Some(app.smart_interact.npc as usize)
    } else {
        None
    };
    let i = app.npcs.iter().enumerate().position(|(idx, n)| {
        n.hp > 0
            && n.kind.is_town_npc_like()
            && (smart_pick == Some(idx)
                || {
                    let (w, h) = n.size();
                    let (lx, ly, hx, hy) = region;
                    // `Rectangle.Intersects` of the region and the NPC box.
                    n.x < hx && n.x + w > lx && n.y < hy && n.y + h > ly
                })
    })?;
    if app.talk_npc == Some(i) {
        return None; // `:43077` — the same NPC re-clicked falls through
    }
    app.talk_npc = Some(i); // `:43081` — `player.SetTalkNPC(i)`
    // `:43081` - `player.SetTalkNPC(i)`: the seam runs the f37 mood capture
    // + the g58 report/settings latch in ONE pass (research/68 §4 - the
    // Princess head draws once per talk change on `NamedRngs::global()`);
    // f37's inline capture here folded into the seam.
    app.set_talk_npc(Some(i));
    // W4-d79 - the orphaned Chat emitter (`Main.cs:43083`,
    // `SoundEngine.PlaySound(24)` - UNPOSITIONED): case 24
    // (`LegacySoundPlayer.cs:957-962`) is Volume/Pan only, NO draws, the
    // slot overwrites WITHOUT a Stop. The play rides the GetChat tail
    // below (the `:43082` -> `:43083` order); the old eager copy here was
    // a duplicated splice and played the cue twice per talk.
    // `NPC.GetChat`'s nextDialogue arm (`NPC.cs:93768-93771`): the Party
    // Girl's FreeCakeDialogue (`ConditionalDialogue.cs:50-64`) - the only
    // registered conditional. The 10-tick CheckDialogue refresh
    // (`NPC.cs:90519-90532`) collapses to the talk: the condition is the
    // `NPC.freeCake` latch a natural party sets (`BirthdayParty.cs:106`).
    // The gift rides `QuickSpawnItem` → `GetOrDropItem` (`Player.cs:7186-
    // 7197`): the inventory slot walk first, the overflow drop at the
    // player centre (the bobber-catch shape); the text's `Next(1, 4)`
    // draw fires AFTER the gift (`:60-63`).
    if app.npcs[i].kind == NpcKind::PartyGirl && app.world_events.free_cake {
        app.world_events.free_cake = false;
        // The cake (3750) stacks to `Item.CommonMaxStack` = 9999 (case 3750
        // writes no maxStack, `Item.cs:33214-33226` → `:49017`) and carries
        // no prefix (the Item-variant QuickSpawnItem - no `Prefix(-1)`
        // roll); the overflow drop's `RequestNewItem` keeps prefix 0.
        let slot = crate::item::slot_for_pickup(&mut app.inventory, 3750, 0);
        match slot {
            Some(s) => app.inventory[s].count += 1,
            None => {
                if let Some(p) = app.player.as_ref() {
                    let (cx, cy) = p.center();
                    crate::world_sim::items::spawn_item_drop_px(
                        &mut app.items,
                        app.rngs.global(),
                        3750,
                        1,
                        Vec2::new(cx, cy),
                    );
                }
            }
        }
        let n = app.rngs.global().next_range(1, 4);
        let text = crate::lang::text(&format!("PartyGirlSpecialText.Cake{n}"));
        app.npc_chat_text = text.clone(); // `:43082`
        // The pending row is consumed with the condition (`ConditionalDialogue.
        // cs:58-66`): the early return skips the generic clear below.
        app.npcs[i].next_dialogue = false;
        return Some(text);
    }
    // W4-f37 — `SetTalkNPC`'s shopping-settings capture
    // (`Player.cs:4387-4390`): `currentShoppingSettings =
    // ShopHelper.GetShoppingSettings(this, npc)` on EVERY talk change —
    // the Nurse's heal cost (`Main.cs:40100`) and the Stylist's prices
    // read this latch, not a per-frame re-scan. The shop-open re-capture
    // (`try_open_town_shop_at_cursor`) stays for the collapsed chat-button
    // entry (the recorded #9 deviation).
    let (pcx, pcy) = app.player.as_ref().map(|p| p.center()).unwrap_or((0.0, 0.0));
    let mood = crate::happiness::process_mood(
        &app.world,
        &app.npcs,
        &app.npcs[i],
        (pcx, pcy),
        app.world.raining,
        app.rngs.global(),
    );
    app.shop_mood = mood.multiplier;
    // The context off the live state. The world flags the port does not
    // carry yet (`Main.remixWorld`, `WorldGen.crimson`) default off —
    // each noted at its field.
    // W4-c39 exec (research/114 §1h): the FreeCake talk arm DROPPED — this
    // was d120's collapse shape with a WORSE gift arm (the C#
    // `GetOrDropItem` fills the inventory FIRST, `Player.cs:7193-7200`;
    // c39 always world-dropped at the NPC centre). research/70 §3's ONE
    // chain (f38 structure + f41 alive gate + d120/f41 gift-before-text
    // order, single-slot fill, global stream) supersedes it — f41c
    // `f1f95be4` is canonical. The `free_cake` field + its writers stay
    // (the scheduler/dusk/clear-world sites); the gift chain lands with
    // the surviving GetChat re-pin at the merge.
    // The context off the live state. The world flags the port does not
    // carry yet (the storm clock, the happy-windy-day, `BirthdayParty`,
    // `LanternNight`, the remix world, the Moon Lord) default off — each
    // noted at its field. `WorldGen.crimson` reads the LIVE `World.crimson`
    // (W4-g69 doc-sweep).
    // carry yet (the storm clock, the happy-windy-day, the remix world,
    // `WorldGen.crimson`) default off — each noted at its field. W4-f38:
    // the party/lantern flags and the Moon Lord latch now read the live
    // schedulers (`world_events`) and the world.
    let day_time = app.world.day_time;
    let time = app.world.time;
    let blood_moon = app.world.blood_moon;
    let eclipse = app.world.eclipse;
    let slime_rain = app.world.slime_rain;
    let hard_mode = app.world.hard_mode;
    let moon_phase = app.world.moon_phase;
    // `Main.raining` — the LIVE rain latch (`Rain.is_raining`, the
    // `Main.cs:64649/:64725` writers); `world.raining` only mirrors it at
    // save (`saveglue.rs:99`), so the talk reads the event state.
    let raining = app.rain.is_raining();
    let (life, life_max, deaths, defense, head) = app
        .player
        .as_ref()
        .map(|p| {
            // `Player.head` (`Player.cs:35765`): the vanity head's slot when
            // one is worn, else the armor head's — `GetEffectiveArmor(10/0)
            // .headSlot`, -1 for air (`Item.cs:48998`'s SetDefaults row).
            // The port has no loadouts, so the slot itself is the source.
            let vanity = crate::registry::get(app.equip.armor[10].kind)
                .map_or(-1, |d| d.head_slot);
            let head = if vanity >= 0 {
                vanity
            } else {
                crate::registry::get(p.equipped[0]).map_or(-1, |d| d.head_slot)
            };
            (p.hp, p.max_hp, p.deaths_pve as i32, p.stat_defense, head)
        })
        .unwrap_or((0, 0, 0, 0, -1));
    // `Player.NormalizedLuck` (`Player.cs:4107-4122`) — the clamped ±cap
    // ratio the wizard's luck-band gate reads.
    let luck = app
        .player
        .as_ref()
        .map_or(0.0, |p| crate::npc_chat::normalized_luck(p.luck()));
    // `Player.Male` (`Player.cs:3405-3409` — `PlayerVariantID.Sets.Male`):
    // the session draft's cloth style decides; a fresh spawn is variant 0
    // (male), the same default the render pass documents.
    let male = app
        .session_draft
        .as_ref()
        .map_or(true, |d| crate::ui::char_creation::is_male(d.skin_variant));
    let angler_quests = app
        .player
        .as_ref()
        .map(|p| p.angler_quests_finished)
        .unwrap_or(0);
    let golfer_score = app.player.as_ref().map(|p| p.golfer_score).unwrap_or(0);
    // `Player.HasItem(5275)` (`Player.cs:55894-55904`): the inventory
    // 0..58 walk with `stack > 0` — the port's grid + trash (the cola is
    // neither coin nor ammo, so those slots can never hold it).
    let has_cola = app
        .inventory
        .iter()
        .chain(std::iter::once(&app.equip.trash))
        .any(|s| s.kind == 5275 && s.count > 0);
    // `DD2Event.DownedInvasionT1/2` — the persisted tier-victory latches
    // (S1-E-12c), NOT the per-run wave-boss death latches.
    let dd2_t1 = app.world.dd2_downed_t1;
    let dd2_t2 = app.world.dd2_downed_t2;
    let dd2_t3 = app.world.dd2_downed_t3;
    let dd2_ongoing = app.world.dd2_event_ongoing;
    // The event-text gates (`NPC.cs:94860-94884`): the graveyard zone,
    // `BirthdayParty.PartyIsUp`, the rain (not storm), the happy windy day
    // and the storm clock — all live App state now.
    let zone_graveyard = app.scene_metrics.zone_graveyard;
    let party_is_up = crate::world_events::party_is_up(&app.world_events);
    let windy_day = app.wind.happy_windy_day;
    let storming = app.wind.storming;
    let lanterns_up = crate::world_events::lanterns_up(&app.world_events);
    let rng = app.rngs.global();
    let mut draw = |n: i32| rng.next_max(n);
    let mut ctx = crate::npc_chat::ChatContext {
        npcs: &app.npcs,
        rng: &mut draw,
        day_time,
        time,
        blood_moon,
        eclipse,
        slime_rain,
        hard_mode,
        moon_phase,
        remix_world: false,    // `Main.remixWorld` — no remix flag in the port
        raining,
        storming,              // `Main.IsItStorming` — the wind storm latch
        windy_day,             // `Main.IsItAHappyWindyDay` — the wind day latch
        zone_graveyard,        // `Player.ZoneGraveyard` — the scene metrics
        party_is_up,           // `BirthdayParty.PartyIsUp` (S1-F-14)
        // W4-c39 exec (research/114 §1h): the live-feed hunks DROP — d120's
        // superset ctx (research/70 drop 8) is the survivor at the merge.
        // `WorldGen.crimson` — the LIVE world evil type (W4-g69 doc-sweep:
        // `World.crimson`, the `.wld` flags byte + the `.trwld` v18 tail).
        crimson: app.world.crimson,
        downed_boss1: app.world.downed_eoc, // `NPC.downedBoss1`
        downed_boss2: app.world.downed_eow, // `NPC.downedBoss2`
        downed_boss3: app.world.downed_skeletron, // `NPC.downedBoss3`
        downed_moonlord: app.world.downed_moon_lord, // `NPC.downedMoonlord`
        dd2_downed_t1: dd2_t1,
        dd2_downed_t2: dd2_t2,
        dd2_downed_t3: dd2_t3,
        dd2_ongoing,
        lanterns_up, // `LanternNight.LanternsUp` (S1-F-14)
        player_life: life,
        player_life_max: life_max,
        player_base_life_max: life_max, // `Player.statLifeMax` — the port keeps one max
        player_defense: defense, // `Player.statDefense` (M3-EQUIP-2)
        player_male: male,       // `Player.Male` — the session draft's cloth style
        player_head: head,       // `Player.head` — the vanity/armor head slot
        player_deaths_pve: deaths,
        player_luck: luck,       // `Player.NormalizedLuck` — the clamped ±cap ratio
        player_has_cola: has_cola,
        angler_quest_finished: app.world.angler_quest_finished, // `Main.anglerQuestFinished`
        angler_quests_finished: angler_quests,
        golfer_score,
    };
    let text = crate::npc_chat::get_chat(&app.npcs[i], &mut ctx);
    // The pending row clears at talk — the C# leaves `nextDialogue` set
    // until the next `CheckDialogue` tick clears it (the condition fell);
    // unobservable either way (the same-NPC re-talk declines `:43077`),
    // the port's early clear is the recorded timing note (research/70 §3).
    app.npcs[i].next_dialogue = false;
    // `FreeCakeDialogue.GetChatAndClearCondition`'s side effects
    // (`ConditionalDialogue.cs:58-66`), AFTER the text draw: the condition
    // clears (`NPC.freeCake = false`), the pending row with it, and the
    // Slice Of Cake (3750) gift rides `QuickSpawnItem(GiftRecieved)` →
    // `GetOrDropItem` — the inventory fills first, the overflow drops at
    // the player centre (the bobber-catch seam, `Player.cs:7187-7200`).
    // The `SendData(51, …, 10f)` net sync has no single-player consumer.
    if app.npcs[i].next_dialogue {
        app.world_events.free_cake = false;
        app.npcs[i].next_dialogue = false;
        let max_stack = crate::registry::max_stack(3750);
        let mut pending = 1u32;
        while pending > 0 {
            let Some(slot) = crate::item::slot_for_pickup(&mut app.inventory, 3750, 0) else {
                break;
            };
            let room = max_stack.saturating_sub(app.inventory[slot].count);
            if room == 0 {
                break;
            }
            let take = pending.min(room);
            app.inventory[slot].count += take;
            pending -= take;
        }
        if pending > 0 {
            if let Some(p) = app.player.as_ref() {
                let (cx, cy) = p.center();
                crate::world_sim::items::spawn_item_drop_px(
                    &mut app.items,
                    app.rngs.stream(RngKey::UpdateItems),
                    3750,
                    pending,
                    glam::Vec2::new(cx, cy),
                );
            }
        }
    }
    app.npc_chat_text = text.clone(); // `:43082` — `Main.npcChatText = GetChat()`
    // `:43083` — `SoundEngine.PlaySound(24)` (`SoundID.Chat`) AFTER the
    // `GetChat` answer, inside the fresh-talk arm (`talkNPC != i`).
    app.audio.play("Chat");
    Some(text)
}

/// The right-click dispatch's Tax Collector arm — the `TaxCollectorCollectTaxes`
/// interaction (`NPCInteractions.cs:221-244`); he offers no shop.
fn try_tax_collect_at_cursor(app: &mut App, world_pos: Vec2) -> Option<usize> {
    app.npcs.iter().position(|n| {
        n.hp > 0 && n.kind == NpcKind::TaxCollector && {
            let (w, h) = n.size();
            world_pos.x >= n.x
                && world_pos.x < n.x + w
                && world_pos.y >= n.y
                && world_pos.y < n.y + h
        }
    })
}

pub(crate) fn try_open_shop_at_cursor(app: &mut App, world_pos: Vec2) -> bool {
    // The bound-goblin rescue (`NPC.cs:19824-19840`'s `talkNPC` trigger +
    // `AI_000_TransformBoundNPC` `:44884-44896`): the talk transforms 105
    // → 107 in place and raises `savedGoblin` — the port falls through to
    // the shop open (the vanilla opens the dialog, the player then picks
    // Shop; the ПКМ-collapse matches the Nurse treatment).
    if let Some(i) = app.npcs.iter().position(|n| {
        n.hp > 0 && n.kind == NpcKind::BoundGoblin && {
            let (w, h) = n.size();
            world_pos.x >= n.x
                && world_pos.x < n.x + w
                && world_pos.y >= n.y
                && world_pos.y < n.y + h
        }
    }) {
        rescue_bound_goblin(&mut app.npcs[i], &mut app.world);
    }
    // The bound Wizard/Mechanic talks (`NPC.cs:19841-19848`'s talk arms):
    // the talk transforms 106 → 108 and 123 → 124 in place and raises
    // the saved flags (`:52948`/`:52951`), which opens the town arrival.
    for (bound, freed, flag) in [
        (NpcKind::BoundWizard, NpcKind::Wizard, "wizard"),
        (NpcKind::BoundMechanic, NpcKind::Mechanic, "mech"),
    ] {
        if let Some(i) = app.npcs.iter().position(|n| {
            n.hp > 0 && n.kind == bound && {
                let (w, h) = n.size();
                world_pos.x >= n.x
                    && world_pos.x < n.x + w
                    && world_pos.y >= n.y
                    && world_pos.y < n.y + h
            }
        }) {
            match flag {
                "wizard" => rescue_bound_wizard(&mut app.npcs[i], &mut app.world),
                _ => rescue_bound_mechanic(&mut app.npcs[i], &mut app.world),
            }
            let _ = freed;
        }
    }
    // The sleeping Golfer's talk (`NPC.cs:19833-19836`): the talk frees
    // him and raises `savedGolfer` (`:52938`).
    if let Some(i) = app.npcs.iter().position(|n| {
        n.hp > 0 && n.kind == NpcKind::SleepingGolfer && {
            let (w, h) = n.size();
            world_pos.x >= n.x
                && world_pos.x < n.x + w
                && world_pos.y >= n.y
                && world_pos.y < n.y + h
        }
    }) {
        rescue_sleeping_golfer(&mut app.npcs[i], &mut app.world);
    }
    // The webbed Stylist's talk (`NPC.cs:19849-19852`): the talk frees
    // him and raises `savedStylist` (`:52953`).
    if let Some(i) = app.npcs.iter().position(|n| {
        n.hp > 0 && n.kind == NpcKind::WebbedStylist && {
            let (w, h) = n.size();
            world_pos.x >= n.x
                && world_pos.x < n.x + w
                && world_pos.y >= n.y
                && world_pos.y < n.y + h
        }
    }) {
        rescue_webbed_stylist(&mut app.npcs[i], &mut app.world);
    }
    // The Sleeping Angler's talk (`NPC.cs:19853-19856`'s `talkNPC`
    // trigger + `AI_000_TransformBoundNPC` `:44884-44896`): the talk
    // transforms 376 → 369 in place, `UpdateSavedStates` (`:52956-52958`)
    // raises `savedAngler`, and `Transform`'s `case 369` (`:81121-81129`)
    // forces the new Angler homeless with his home at his feet — the
    // port drops the home (the town pass re-anchors him).
    if let Some(i) = app.npcs.iter().position(|n| {
        n.hp > 0 && n.kind == NpcKind::SleepingAngler && {
            let (w, h) = n.size();
            world_pos.x >= n.x
                && world_pos.x < n.x + w
                && world_pos.y >= n.y
                && world_pos.y < n.y + h
        }
    }) {
        rescue_bound_angler(&mut app.npcs[i], &mut app.world);
    }
    // The Angler's quest turn-in (`NPCInteractions.cs:519`'s `AnglerQuest`
    // → `Main.NPCChatText_DoAnglerQuest`, `Main.cs:40227-40263`): the
    // hand-in of today's quest fish — the vanilla's chat-button collapse,
    // the Nurse treatment.
    if let Some(i) = app.npcs.iter().position(|n| {
        n.hp > 0 && n.kind == NpcKind::Angler && {
            let (w, h) = n.size();
            world_pos.x >= n.x
                && world_pos.x < n.x + w
                && world_pos.y >= n.y
                && world_pos.y < n.y + h
        }
    }) {
        return angler_turn_in(app, i);
    }
    // The Tax Collector's right arm (`NPCInteractions.cs:221-244`'s
    // `TaxCollectorCollectTaxes`): he offers no shop — the click pays the
    // tax purse out (`Main.NPCChatText_DoTaxCollector`). The vanilla
    // button exists only while TALKING (`Condition: TalkNPCType == 441`,
    // `:223-226`), so the payout reads the talk-open latch
    // (`Player.cs:4389`); the port's collapse latches on the first press
    // (`talk_to_npc` ran ahead of this dispatch) and the same-NPC re-click
    // falls through WITHOUT re-latching (`Main.cs:43077`). A direct call
    // with no latch (the headless tests) keeps `NotInShop`'s 1.0.
    if let Some(i) = try_tax_collect_at_cursor(app, world_pos) {
        if app.talk_npc != Some(i) {
            app.set_talk_npc(Some(i)); // the collapsed first-press latch
        }
        return tax_collector_payout(app, i);
    }
    // The Dye Trader's Strange Plants turn-in (`NPCInteractions.cs:443-463`'s
    // `DyeTraderRarePlant` → `Main.NPCChatText_DyeTraderRarePlant`,
    // `Main.cs:40002-40020`): the button collapses onto the right-click (the
    // Angler/Nurse treatment) — a plant in hand trades for a dye reward, an
    // empty hand draws the NoPlant line. The button's hard-mode `Condition`
    // (`:445-452`) is a UI gate; the `Interact` body carries none, so the
    // collapse runs unconditionally like the Angler turn-in's.
    if let Some(i) = app.npcs.iter().position(|n| {
        n.hp > 0 && n.kind == NpcKind::DyeTrader && {
            let (w, h) = n.size();
            world_pos.x >= n.x
                && world_pos.x < n.x + w
                && world_pos.y >= n.y
                && world_pos.y < n.y + h
        }
    }) {
        return dye_trader_turn_in(app, i);
    }
    // The town dispatch: the Nurse heals (the vanilla's dialog-button pair
    // — the port collapses them onto the right-click). The cost reads the
    // TALK-OPEN LATCH (`App.shopping_settings`, `Player.cs:4389`) — the
    // first press latched through `talk_to_npc`; the same-NPC re-click
    // falls through here WITHOUT re-latching, exactly the C# button reading
    // `currentShoppingSettings` (`Main.GetNurseHealCost`, `Main.cs:40100`).
    let Some(_nurse_idx) = app.npcs.iter().position(|n| {
        n.hp > 0 && n.kind == NpcKind::Nurse && {
            let (w, h) = n.size();
            world_pos.x >= n.x
                && world_pos.x < n.x + w
                && world_pos.y >= n.y
                && world_pos.y < n.y + h
        }
    }) else {
        return try_open_town_shop_at_cursor(app, world_pos);
    };
    let healed = app.nurse_heal();
    // `Main.NPCChatText_DoNurseHeal`'s tail (`Main.cs:40177`): the hop is
    // UNCONDITIONAL — every arm (paid, short purse, nothing to heal).
    crate::ui::npc_chat::do_npc_portrait_hop(app);
    healed
}

/// `Main.CanStartInvasion` (`Main.cs:64414-64432`): `invasionType != 0`
/// blocks (every invasion type, not just the goblins), plus at least one
/// qualifying player — the 200-life gate (`statLifeMax >= 200`); the
/// multiplayer count folds to the session player. The item path passes
/// `ignoreDelay: true`, so the `invasionDelay` scouting arm folds out.
pub(crate) fn can_start_invasion(world: &tr_core::World, player_life_max: i32) -> bool {
    world.invasion_type == 0 && player_life_max >= 200
}

/// `Main.StartInvasion(type)` (`Main.cs:64435-64486`): the stale-type
/// clear, the active-invasion early return, the size
/// `80 + 40 x the qualifying players` (+40+20x for the pirates' type 3,
/// `160 + 40x` for the martians' type 4), the full march/warn state and
/// the `Next(2)` side roll. `rng` is the caller's `Main.rand` — the
/// `UpdateTime` stream from the morning roll, `UpdatePlayers` from the
/// items, the bare stream from the debug panel.
pub(crate) fn start_invasion(
    world: &mut tr_core::World,
    qualifying_players: i32,
    invasion_type: i32,
    rng: &mut UnifiedRandom,
) -> bool {
    // `:64437-64444`: a finished invasion clears its stale type, then any
    // live one refuses the new start.
    if world.invasion_type != 0 && world.invasion_size == 0 {
        world.invasion_type = 0;
    }
    if world.invasion_type != 0 {
        return false;
    }
    // `:64445-64453`: the start needs at least one live 200+-life player —
    // with none the C# does nothing (the type is never assigned).
    if qualifying_players <= 0 {
        return false;
    }
    let n = qualifying_players;
    // The panel/kill paths read the goblin flag (C# only has the type).
    world.invasion_type = invasion_type;
    world.invasion_goblins = invasion_type == 1;
    // `:64456-64464`: the base 80+40x; the pirates (type 3) add 40+20x,
    // the martians (type 4) use 160+40x.
    world.invasion_size = 80 + 40 * n;
    if invasion_type == 3 {
        world.invasion_size += 40 + 20 * n;
    }
    if invasion_type == 4 {
        world.invasion_size = 160 + 40 * n;
    }
    world.invasion_size_start = world.invasion_size;
    world.invasion_warn = 0;
    // `:64471-64483`: the martians telegraph from one tile west of spawn with
    // `invasionWarn = 2`; every other type marches in from a random side.
    if invasion_type == 4 {
        world.invasion_x = world.spawn_x as f64 - 1.0;
        world.invasion_warn = 2;
    } else {
        // `Main.rand.Next(2) == 0 → invasionX = 0` else `maxTilesX`.
        world.invasion_x = if rng.next_max(2) == 0 {
            0.0
        } else {
            world.width as f64
        };
    }
    true
}

/// `Main.StartInvasion`'s whole body (`Main.cs:64435-64486`) for an `App`:
/// the `World` half plus the progress-dial fields that live on the host
/// (`invasionProgress`/`Icon`/`Wave`/`Max`, `:64466-64469`). Returns whether
/// the invasion actually started (the C# gives no answer; the callers need
/// one to decide on the sound/chat side effects).
///
/// `key: None` is the bare `Main.rand` — the debug console is the chat
/// command dispatcher's stand-in (S1-E-29), which the C# runs outside every
/// `Main.SwapRandom` block.
pub(crate) fn start_invasion_in(
    app: &mut App,
    qualifying_players: i32,
    invasion_type: i32,
    key: Option<crate::app::RngKey>,
) -> bool {
    let rng = match key {
        Some(k) => app.rngs.stream(k),
        None => app.rngs.global(),
    };
    if !start_invasion(&mut app.world, qualifying_players, invasion_type, rng) {
        return false;
    }
    app.invasion_progress = 0;
    app.invasion_progress_icon = invasion_type + 3;
    app.invasion_progress_wave = 0;
    app.invasion_progress_max = app.world.invasion_size_start;
    true
}

/// `NPCID.Sets.MPAllowedEnemies` (`NPCID.cs:10458`): the boss types a client
/// may summon through `61 SpawnBossInvader` (`MessageBuffer.cs:2748`).
const MP_ALLOWED_ENEMIES: [i32; 17] = [
    4, 13, 50, 126, 125, 134, 127, 128, 131, 129, 130, 222, 245, 266, 370, 657, 668,
];

/// `NPC.SpawnOnPlayer` (`NPC.cs:80475-80633`) for the `61` reader: the
/// MPAllowedEnemies boss spawn at the player. The 245 Golem's altar scan, the
/// 370 Fishron's bobber scan and the 398 Moon Lord arm are the special cases;
/// the rest ride the generic `GetSpawnArea` candidate scan.
///
/// Deviations (ANALYSIS "Net apply arms (W4-g49)"): the scan is the port's
/// simplified surface placement (the `spawn_eye_of_cthulhu` precedent — the
/// 500×50 off-screen candidate fidelity is the M4-BOSS polish follow-up); the
/// 245 altar scan / 370 bobber scan / 398 Moon Lord and the `SpawnBoss`
/// mecha-mayhem + `timeLeft *= 20` tails are unported; the `Announcement.
/// HasAwoken` broadcast rides the port's literal stand-in.
pub(crate) fn spawn_on_player(app: &mut App, plr: u8, npc_type: i32) {
    if !MP_ALLOWED_ENEMIES.contains(&npc_type) {
        return;
    }
    // The subject player: slot 0 is the host, the peers ride remote_players.
    let (px, py) = if plr == 0 {
        match app.player.as_ref() {
            Some(p) => p.center(),
            None => return,
        }
    } else {
        match app.remote_players.get(&(plr as u32)) {
            Some(p) => (p.x + crate::player::WIDTH * 0.5, p.y + crate::player::HEIGHT * 0.5),
            None => return,
        }
    };
    let Some(kind) = boss_kind_of(npc_type) else {
        return; // the kind is unported (Betsy 657, the 128-131 bosses)
    };
    if app.npcs.iter().any(|n| n.kind == kind && n.hp > 0) {
        return; // `NPC.AnyNPCs` — the boss is already up
    }
    let xt = ((px / TILE_PX) as i32).clamp(2, app.world.width - 3);
    let yt = ((py / TILE_PX) as i32).clamp(2, app.world.height - 3);
    let boss = match kind {
        NpcKind::KingSlime => Npc::spawn_king_slime(&app.world, xt),
        NpcKind::EyeOfCthulhu => Npc::spawn_eye_of_cthulhu(&app.world, px, py),
        NpcKind::EaterOfWorldsHead | NpcKind::TheDestroyer => {
            let mut h = Npc::spawn_worm_head(&app.world, xt, yt, kind);
            h.hp = h.max_hp;
            h.worm_left = if kind == NpcKind::EaterOfWorldsHead { 65 } else { 80 };
            Some(h)
        }
        _ => {
            let mut b = Npc::new(kind, px, py, 1, 0.0);
            b.hp = b.max_hp;
            Some(b)
        }
    };
    let Some(mut boss) = boss else {
        return;
    };
    boss.target = plr as i32;
    boss.net_update = true;
    app.npcs.push(boss);
    // `NPC.SpawnBoss`' `Announcement.HasAwoken` broadcast (`NPC.cs:80703`).
    let name = crate::lang::npc_name(npc_type);
    let text = crate::lang::text_args("Announcement.HasAwoken", &[name]);
    crate::chat::broadcast_death_text(&mut app.chat, &text, crate::chat::COLOR_BOSS_OR_EVENT);
}

/// The `61` selector's vanilla boss type → the port kind. `None` = unported.
fn boss_kind_of(npc_type: i32) -> Option<NpcKind> {
    Some(match npc_type {
        4 => NpcKind::EyeOfCthulhu,
        13 => NpcKind::EaterOfWorldsHead,
        50 => NpcKind::KingSlime,
        125 => NpcKind::Retinazer,
        126 => NpcKind::Spazmatism,
        127 => NpcKind::SkeletronPrime,
        134 => NpcKind::TheDestroyer,
        222 => NpcKind::QueenBee,
        245 => NpcKind::Golem,
        266 => NpcKind::BrainOfCthulhu,
        370 => NpcKind::DukeFishron,
        668 => NpcKind::Deerclops,
        _ => return None,
    })
}

/// The kind → the shop number (`NPCInteractions.cs:488-498`'s registry:
/// `Shop(17, 1)`, `Shop(19, 2)` … `Shop(107, 6)` — the port keeps the
/// vanilla indices). `None` = no shop (the Guide).
pub(crate) fn shop_index_for_kind(kind: NpcKind) -> Option<u32> {
    Some(match kind {
        NpcKind::Merchant => 1,
        NpcKind::ArmsDealer => 2,
        NpcKind::Dryad => 3,
        NpcKind::Demolitionist => 4,
        NpcKind::Clothier => 5,
        NpcKind::GoblinTinkerer => 6,
        NpcKind::Painter => 15,
        NpcKind::WitchDoctor => 16,
        NpcKind::TravellingMerchant => 19,
        NpcKind::Wizard => 7,
        NpcKind::Mechanic => 8,
        NpcKind::Stylist => 18,
        NpcKind::Golfer => 22,
        NpcKind::Zoologist => 23,
        NpcKind::Princess => 24,
        NpcKind::DyeTrader => 12,
        NpcKind::PartyGirl => 13,
        // W4-d120 final census: the claimed kinds' registry rows —
        // `Shop(142, 9)`/`Shop(160, 10)`/`Shop(178, 11)`/`Shop(209, 14)`
        // (`:496-501`). The STOCK for 9/10/11/14 is d122's lane (its
        // shop.rs already carries the four cases, `Chest.cs:2091-2135`/
        // `:2360`); until it merges these indices resolve empty stock.
        NpcKind::SantaClaus => 9,
        NpcKind::Truffle => 10,
        NpcKind::Steampunker => 11,
        NpcKind::Cyborg => 14,
        // The sibling lanes' kinds (type-keyed arms' shop twins):
        // `Shop(229, 17)` (`:504`, d37's Pirate), `Shop(453, 20)`
        // (`:507`, d40's SkeletonMerchant). `Shop(550, 21)` (`:508`)
        // is d122's row (its shop-currency lane lands the Tavernkeep
        // mapping WITH the medal stock) — not duplicated here.
        _ => match kind.cs_id() {
            229 => 17,
            453 => 20,
            _ => return None,
        },
        // W4-d123: `Shop(550, 21)` (`NPCInteractions.cs:508`) — the
        // Tavernkeep's medal shop. The Skeleton Merchant's `Shop(453, 20)`
        // (`:507`) has no ported kind yet (the shop itself is ported).
        NpcKind::DD2Bartender => 21,
        _ => return None,
    })
}

/// The talk-rescue (`AI_000_TransformBoundNPC`, `NPC.cs:44884-44896`): the
/// bound goblin transforms into the Tinkerer in place — the freed 18x40
/// stats restore (`SetDefaults` 107, `:10271-10283`), `savedGoblin`
/// raises (`:52944-52946`) and the tied state never returns.
pub(crate) fn rescue_bound_goblin(n: &mut Npc, world: &mut tr_core::World) {
    n.kind = NpcKind::GoblinTinkerer;
    n.max_hp = NpcKind::GoblinTinkerer.max_hp();
    n.hp = n.max_hp;
    world.saved_goblin = true;
    name_the_freed_town_npc(n, world);
}

/// `NPC.Transform`'s tail (`NPC.cs:81137`): every rescue re-runs
/// `GiveTownUniqueDataToNPCsThatNeedIt` for the NEW type — the freed NPC
/// names himself. All six rescue targets are legacy profiles (variation 0,
/// `Profiles.cs:83-91`), so the `Main.rand` stand-in is never drawn; the
/// name draws ride `WorldGen.genRand` (`World::frame_rng`).
fn name_the_freed_town_npc(n: &mut Npc, world: &mut tr_core::World) {
    let mut main_rand = tr_core::unified_random::UnifiedRandom::new(world.seed as i32);
    crate::npc_names::give_town_unique_data(n, &mut main_rand, &mut world.frame_rng);
}

