        let gore = &mut app.gore;
        let entity_lights = &mut app.entity_lights;
        // W4-d22: the EoC's spin hand-off gore burst (`NPC.cs:20365-20370`)
        // draws Main.rand through the live gore pool on the UpdateNPCs
