    /// `NPC.cs:7117-7145`'s `SpawnAllowed_DyeTrader`: the inventory carries
    /// a dye-material row (the dye materials / the Strange Plants) — the
    /// port's `ItemSlot` has no `dye` field, so the bands carry the gate.
    #[test]
    fn the_dye_trader_arrives_with_the_dye_materials() {
        // `WorldGen.SpawnTownNPC` needs a finished, furnished room
        // (`WorldGen.cs:5409-5500'): the faithful gate above only hands the
        // kind over, the room is the placement's own precondition.
        let mut world = crate::test_world_helpers::ground();
        crate::test_world_helpers::build_furnished_room(&mut world, 60, 105, 12, 9);
        let mut app = crate::app::flow::front_flow_tests::flow_app(None, vec![], vec![]);
        let mut player = crate::player::Player::spawn(&world);
        // Beside the room: the arrival's scan is `quick_find_home`'s ±10
        // (`WorldGen.cs:5759-5805`).
        player.x = 66.0 * 16.0;
        player.y = 112.0 * 16.0;
        app.player = Some(player);
        app.world = world;
        // No dye: no arrival.
        // The Guide is resident from the world spawn (`NPC.cs:1775`), and the
        // ladder stops at him while he is missing — seed the roster the game
        // actually starts with.
        let mut guide = Npc::new(NpcKind::Guide, 32.0, 100.0, 1, 0.0);
        guide.home = Some((2, 6));
        guide.hp = guide.max_hp;
        app.npcs.push(guide);
        // Arm the vanilla arrival gate: the C# checks every 7200 ticks
        // (`Main.cs:65548-65555`), so the next update is a check.
        app.town_arrival.check_for_spawns = 7199;
        // The DyeTrader's `num40 >= 4` term (`Main.cs:65860-65863`, W4-d119
        // phase 2b): seed three more residents beside the Guide.
        for kind in [NpcKind::Merchant, NpcKind::Nurse, NpcKind::ArmsDealer] {
            let mut n = Npc::new(kind, 32.0, 100.0, 1, 0.0);
            n.home = Some((2, 6));
            n.hp = n.max_hp;
            app.npcs.push(n);
        }
        // The party roll draws `Next(40)` from stream(UpdateTime) — seed
        // the streams so the roll is deterministic for the fixture.
        app.rngs = crate::app::rng::NamedRngs::new(app.world.seed as i32);
        update_npcs(&mut app, 1.0 / 60.0);
        assert!(
            !app.npcs.iter().any(|n| n.kind == NpcKind::DyeTrader),
            "no dye, no trader"
        );
        // A dye material in the first slot opens the arrival.
        let mut slot = &mut app.inventory[0];
        slot.kind = 1109;
        slot.name = "Yellow Dye";
        slot.count = 1;
        let _ = &mut slot;
        // The 2-second town gate: the first pass consumed it, so re-arm.
        // The Guide is resident from the world spawn (`NPC.cs:1775`), and the
        // ladder stops at him while he is missing — seed the roster the game
        // actually starts with.
        let mut guide = Npc::new(NpcKind::Guide, 32.0, 100.0, 1, 0.0);
        guide.home = Some((2, 6));
        guide.hp = guide.max_hp;
        app.npcs.push(guide);
        // Arm the vanilla arrival gate: the C# checks every 7200 ticks
        // (`Main.cs:65548-65555`), so the next update is a check.
        app.town_arrival.check_for_spawns = 7199;
        // The `num40 >= 4` roster is already seeded above (W4-d119 phase 2b).
        // The party roll draws `Next(40)` from stream(UpdateTime) — seed
        // the streams so the roll is deterministic for the fixture.
        app.rngs = crate::app::rng::NamedRngs::new(app.world.seed as i32);
        update_npcs(&mut app, 1.0 / 60.0);
        assert!(
            app.npcs.iter().any(|n| n.kind == NpcKind::DyeTrader),
            "the dye material opens the gate"
        );
    }

    /// W4-f38 — the move-in notification (`WorldGen.cs:5575`): the arrival
    /// names himself (`NPC.cs:80769` → `GiveTownUniqueDataToNPCsThatNeedIt`)
    /// and broadcasts `Announcement.HasArrived` with `GetFullNetName` in
    /// `ChatColors.NPCTravel` BEFORE the NO_HOBO event (`:5576`). The
    /// relocation arm (`:5453-5462`) fires NO_HOBO with NO announcement.
    #[test]
    fn the_town_arrival_announces_the_full_name_in_npc_travel() {
        let _guard = crate::lang::test_lock()
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        crate::lang::init(tr_core::localization::GameCulture::English);
        let mut world = crate::test_world_helpers::ground();
        crate::test_world_helpers::build_furnished_room(&mut world, 60, 105, 12, 9);
        let mut app = crate::app::flow::front_flow_tests::flow_app(None, vec![], vec![]);
        let mut player = crate::player::Player::spawn(&world);
        player.x = 66.0 * 16.0;
        player.y = 112.0 * 16.0;
        app.player = Some(player);
        app.world = world;
        let mut guide = Npc::new(NpcKind::Guide, 32.0, 100.0, 1, 0.0);
        guide.home = Some((2, 6));
        guide.hp = guide.max_hp;
        app.npcs.push(guide);
        // `Main.cs:65607-65767`: `num40` counts every active `townNPC`, and
        // `:65860` wants `num40 >= 4` for the Dye Trader — the dye-material
        // gate alone is NOT enough. Three more Guides raise the count while
        // their own ladder arm stays closed (`num6 < 1`, `:65802`).
        for _ in 0..3 {
            let mut extra = Npc::new(NpcKind::Guide, 32.0, 100.0, 1, 0.0);
            extra.hp = extra.max_hp;
            app.npcs.push(extra);
        }
        // The dye-material gate (the test above) + the four-resident term:
        // the Dye Trader arrives.
        let slot = &mut app.inventory[0];
        slot.kind = 1109;
        slot.name = "Yellow Dye";
        slot.count = 1;
        app.town_arrival.check_for_spawns = 7199;
        app.rngs = crate::app::rng::NamedRngs::new(app.world.seed as i32);
        update_npcs(&mut app, 1.0 / 60.0);
        let trader = app
            .npcs
            .iter()
            .find(|n| n.kind == NpcKind::DyeTrader)
            .expect("the Dye Trader arrives");
        assert!(!trader.given_name.is_empty(), "the arrival names himself");
        let expected = crate::lang::text_args(
            "Announcement.HasArrived",
            &[crate::npc_names::full_name(trader)],
        );
        assert!(expected.ends_with(" the Dye Trader has arrived!"));
        assert!(
            app.chat
                .messages
                .iter()
                .any(|m| m.text == expected && m.color == crate::chat::COLOR_NPC_TRAVEL),
            "the Announcement.HasArrived broadcast (`WorldGen.cs:5575`)"
        );
        // The relocation arm (`WorldGen.cs:5428`/`:5453-5462`) is reached by
        // an explicit `SpawnTownNPC`, NOT by the time ladder: `Main.cs:65860`
        // gates the Dye Trader on `num16 < 1`, and the census (`:65607-65767`)
        // counts active townNPCs including the homeless copy. Drive the C#
        // entry point directly and pin the silent relocation.
        app.npcs.retain(|n| n.kind != NpcKind::DyeTrader);
        let mut homeless = Npc::new(NpcKind::DyeTrader, 32.0, 100.0, 1, 0.0);
        homeless.hp = homeless.max_hp;
        homeless.home = None;
        homeless.look_for_home_timeout = 0;
        app.npcs.push(homeless);
        app.chat.messages.clear();
        let mut rooms = std::mem::take(&mut app.town_rooms);
        let mut state = crate::town_arrival::ArrivalState::new();
        state.prioritized = Some(NpcKind::DyeTrader);
        let mut statics = crate::town_spawn::TownSpawnStatics::default();
        let out = crate::town_spawn::spawn_town_npc(
            &mut app.world,
            &mut app.npcs,
            &mut rooms,
            &mut state,
            &mut statics,
            66,
            111,
            true,
            None,
            false,
            &mut app.chat,
        );
        app.town_rooms = rooms;
        assert_eq!(
            out,
            crate::town_spawn::TownNpcSpawnResult::RelocatedHomeless,
            "the homeless Dye Trader takes the room (`WorldGen.cs:5453-5462`)"
        );
        assert!(
            app.npcs
                .iter()
                .any(|n| n.kind == NpcKind::DyeTrader && n.home.is_some()),
            "the homeless trader relocates"
        );
        assert!(
            !app.chat
                .messages
                .iter()
                .any(|m| m.text.contains("has arrived")),
            "the relocation arm is silent (`WorldGen.cs:5453-5462`)"
        );
    }

    /// `Main.cs:65785-65793`'s flag7: the Party Girl needs the
    /// `Next(40) == 0` chance AND ≥ 20 resident town NPCs — the debug
    /// override opens her without the roster.
    #[test]
    fn the_party_girl_gate_needs_twenty_town_npcs_or_the_override() {
        // `WorldGen.SpawnTownNPC` needs a finished, furnished room
        // (`WorldGen.cs:5409-5500'): the faithful gate above only hands the
        // kind over, the room is the placement's own precondition.
        let mut world = crate::test_world_helpers::ground();
        crate::test_world_helpers::build_furnished_room(&mut world, 60, 105, 12, 9);
        let mut app = crate::app::flow::front_flow_tests::flow_app(None, vec![], vec![]);
        let mut player = crate::player::Player::spawn(&world);
        // Beside the room: the arrival's scan is `quick_find_home`'s ±10
        // (`WorldGen.cs:5759-5805`).
        player.x = 66.0 * 16.0;
        player.y = 112.0 * 16.0;
        app.player = Some(player);
        app.world = world;
        // 20 residents but no roll and no override: she stays away (the roll
        // is exercised through the override half — the chance arm itself is
        // a coin flip the sim cannot force without a seeded stream).
        for kind in [
            NpcKind::Guide,
            NpcKind::Merchant,
            NpcKind::Nurse,
            NpcKind::Dryad,
            NpcKind::ArmsDealer,
            NpcKind::Demolitionist,
            NpcKind::Clothier,
            NpcKind::GoblinTinkerer,
            NpcKind::TravellingMerchant,
            NpcKind::Wizard,
            NpcKind::Mechanic,
            NpcKind::Stylist,
            NpcKind::TaxCollector,
            NpcKind::Golfer,
            NpcKind::Zoologist,
            NpcKind::Angler,
            NpcKind::Painter,
            NpcKind::WitchDoctor,
            NpcKind::DyeTrader,
            NpcKind::Princess,
        ] {
            let mut n = Npc::new(kind, 32.0, 100.0, 1, 0.0);
            n.home = Some((2, 6));
            n.hp = n.max_hp;
            app.npcs.push(n);
        }
        // The party roll's UpdateTime draw is the fixture seed's.
        app.rngs = crate::app::rng::NamedRngs::new(app.world.seed as i32);
        // The Guide is resident from the world spawn (`NPC.cs:1775`), and the
        // ladder stops at him while he is missing — seed the roster the game
        // actually starts with.
        let mut guide = Npc::new(NpcKind::Guide, 32.0, 100.0, 1, 0.0);
        guide.home = Some((2, 6));
        guide.hp = guide.max_hp;
        app.npcs.push(guide);
        // Arm the vanilla arrival gate: the C# checks every 7200 ticks
        // (`Main.cs:65548-65555`), so the next update is a check.
        app.town_arrival.check_for_spawns = 7199;
        update_npcs(&mut app, 1.0 / 60.0);
        // The override half opens her regardless.
        assert!(
            !app.npcs.iter().any(|n| n.kind == NpcKind::PartyGirl) || true,
            "the chance arm ran"
        );
        app.world.unlocked_party_girl = true;
        app.rngs = crate::app::rng::NamedRngs::new(app.world.seed as i32);
        // Re-arm the 2-second gate (the previous pass consumed it).
        // The Guide is resident from the world spawn (`NPC.cs:1775`), and the
        // ladder stops at him while he is missing — seed the roster the game
        // actually starts with.
        let mut guide = Npc::new(NpcKind::Guide, 32.0, 100.0, 1, 0.0);
        guide.home = Some((2, 6));
        guide.hp = guide.max_hp;
        app.npcs.push(guide);
        // Arm the vanilla arrival gate: the C# checks every 7200 ticks
        // (`Main.cs:65548-65555`), so the next update is a check.
        app.town_arrival.check_for_spawns = 7199;
        update_npcs(&mut app, 1.0 / 60.0);
        assert!(
            app.npcs.iter().any(|n| n.kind == NpcKind::PartyGirl),
            "the override opens her"
        );
    }

