    #[test]
    fn the_carrier_chain_leaves_no_orphans_and_no_segment_loot() {
        // The ROADMAP's S1-D-6 criterion — the chain's integrity. The
        // segments share the carrier's life (`NPC.realLife`,
        // `NPC.cs:81374-81378`) and die with it; `NPC.checkDead`'s carrier
        // guard (`NPC.cs:78040-78042`) keeps the loot, the coins and the
        // bestiary credit on the carrier alone.
        let (mut app, mut player) = {
            let mut a = flow_app(None, vec![], vec![]);
            let p = Player::spawn(&a.world);
            (a, p)
        };
        let world = fixture();
        app.npcs.push(Npc::new(
            NpcKind::DevourerHead,
            150.0 * TILE_PX,
            112.0 * TILE_PX,
            1,
            0.0,
        ));
        app.npcs[0].hp = app.npcs[0].max_hp;
        // Assemble the chain through the worm pass.
        let mut rng = UnifiedRandom::new(7);
        let mut next_id = 1u32;
        for _ in 0..4 {
            crate::world_sim::npcs::update_worms_in(
                &world,
                Some(player.center()),
                &mut app.npcs,
                &mut rng,
                &mut next_id,
            );
        }
        assert!(
            app.npcs.len() >= 10,
            "the chain assembled ({})",
            app.npcs.len()
        );
        let items_before = app.items.len();
        // The carrier dies: the pool is empty, so the whole chain falls.
        app.npcs[0].hp = 0;
        crate::world_sim::npcs::update_worms_in(
            &world,
            Some(player.center()),
            &mut app.npcs,
            &mut rng,
            &mut next_id,
        );
        assert!(
            app.npcs.iter().all(|n| n.hp <= 0),
            "no orphan survives the carrier"
        );
        // The death sweep: the carrier's loot only.
        update_npcs(&mut app, 1.0 / 60.0);
        assert!(
            app.npcs.iter().all(|n| n.kind != NpcKind::DevourerHead),
            "the whole chain is gone"
        );
        let dropped = app.items.len() - items_before;
        // The control: the same carrier on its own drops exactly the same
        // — the links drop nothing.
        let (mut control, _cplayer) = {
            let mut a = flow_app(None, vec![], vec![]);
            let p = Player::spawn(&a.world);
            (a, p)
        };
        control.npcs.push(Npc::new(
            NpcKind::DevourerHead,
            150.0 * TILE_PX,
            112.0 * TILE_PX,
            1,
            0.0,
        ));
        control.npcs[0].hp = 0;
        update_npcs(&mut control, 1.0 / 60.0);
        assert_eq!(
            dropped,
            control.items.len(),
            "the segments drop nothing — only the carrier's loot"
        );
    }

    #[test]
    fn the_stardust_worm_fires_the_mark_on_the_570th_tick() {
        // `AI_006`'s 402 arm (`NPC.cs:51030-51073`): the 600-tick cycle
        // decelerates over [285, 570] and fires the mark request at 570,
        // re-normalising the velocity to 6.
        let (_app, mut player) = {
            let mut a = flow_app(None, vec![], vec![]);
            let p = Player::spawn(&a.world);
            (a, p)
        };
        let world = fixture();
        let mut n = Npc::new(
            NpcKind::StardustWormHead,
            150.0 * TILE_PX,
            108.0 * TILE_PX,
            1,
            0.0,
        );
        n.hp = n.max_hp;
        n.ai[2] = 569.0;
        player.x = 170.0 * TILE_PX;
        player.y = 118.0 * TILE_PX;
        let mut rng = UnifiedRandom::new(7);
        n.update_rng(&world, &mut player, 1.0 / 60.0, &mut rng);
        assert!(n.wants_stardust_mark, "the mark fires at the 570th tick");
        let speed = (n.vx * n.vx + n.vy * n.vy).sqrt();
        assert!(
            (speed - 6.0).abs() < 0.1,
            "the velocity re-normalises to 6: {}",
            speed
        );
        // The cycle resets at 600.
        n.ai[2] = 599.0;
        n.update_rng(&world, &mut player, 1.0 / 60.0, &mut rng);
        assert_eq!(n.ai[2], 0.0, "the counter resets");
    }

    /// W4-f4 — sites 51046/51054 (`NPC.cs:51039-51060`): the 570th-tick
    /// burst is 50 iterations; each draws the shared NextVector2Circular
    /// (one NextFloat angle + one NextFloat radial), then the type-180
    /// gate Next(2) and the type-176 gate Next(2). A passed gate rolls
    /// new_dust (type 180/176, alpha 100) then the scale add (Next(50)),
    /// noGravity, velocity = vector, fadeIn NextFloat*1.5. A mirrored
    /// stream re-derives every draw in order. WRITTEN NOT RUN.
    #[test]
    #[ignore = "dust rings are a deferred production deviation (npc.rs ANALYSIS); the mirror oracle stays pinned until the arm lands"]
    fn w4_f4_the_stardust_worm_burst_mirrors_the_fifty_iterations() {
        let world = fixture();
        let mut player = Player::spawn(&world);
        player.x = 170.0 * TILE_PX;
        player.y = 118.0 * TILE_PX;
        let mut n = Npc::new(NpcKind::StardustWormHead, 150.0 * TILE_PX, 108.0 * TILE_PX, 1, 0.0);
        n.hp = n.max_hp;
        n.ai[2] = 569.0; // -> 570: the burst tick
        let ctx = crate::npc::permissive_dust_ctx(&world);
        let mut pool = tr_core::particles::DustPool::new();
        let mut rng = UnifiedRandom::new(23);
        let mut mirror = UnifiedRandom::new(23);
        let mut mpool = tr_core::particles::DustPool::new();
        // The mirror re-derives the burst at the PRE-renormalize position
        // (the machine spawns before the velocity renormalize + the move).
        let (px, py) = (n.x, n.y);
        let (pw, ph) = n.size();
        let mut expected = 0usize;
        for _ in 0..50 {
            let ang = mirror.next_float() * std::f32::consts::TAU;
            let radial = mirror.next_float();
            let vector = glam::Vec2::new(ang.cos() * 8.0 * radial, ang.sin() * 8.0 * radial);
            if mirror.next_max(2) == 0 {
                let idx = mpool.new_dust(
                    &mut mirror, &ctx, &world, glam::Vec2::new(px, py),
                    pw as i32, ph as i32, 180, 0.0, 0.0, 100,
                    tr_core::particles::Color::default(), 1.0,
                );
                let dd = mpool.slot_mut(idx);
                dd.scale += mirror.next_max(50) as f32 * 0.04;
                dd.no_gravity = true;
                dd.velocity = vector;
                dd.fade_in = mirror.next_float() * 1.5;
                expected += 1;
            }
            if mirror.next_max(2) == 0 {
                let idx = mpool.new_dust(
                    &mut mirror, &ctx, &world, glam::Vec2::new(px, py),
                    pw as i32, ph as i32, 176, 0.0, 0.0, 100,
                    tr_core::particles::Color::default(), 1.0,
                );
                let dd = mpool.slot_mut(idx);
                dd.scale += 0.3 + mirror.next_max(50) as f32 * 0.01;
                dd.no_gravity = true;
                dd.velocity = vector;
                dd.fade_in = mirror.next_float() * 1.5;
                expected += 1;
            }
        }
        n.update_rng(&world, &mut player, 1.0 / 60.0, &mut rng);
        let act: Vec<usize> = (0..6000).filter(|&i| pool.slot(i).active).collect();
        assert_eq!(act.len(), expected, "the 50-iteration burst count");
        for (k, &i) in act.iter().enumerate() {
            assert!(pool.slot(i).dust_type == 180 || pool.slot(i).dust_type == 176);
            assert!(pool.slot(i).no_gravity);
            assert_eq!(pool.slot(i).velocity, mpool.slot(k).velocity);
            assert_eq!(pool.slot(i).scale, mpool.slot(k).scale);
            assert_eq!(pool.slot(i).fade_in, mpool.slot(k).fade_in);
        }
        assert_eq!(rng.next_range(0, 1000), mirror.next_range(0, 1000));
    }

    // ---- W-A2-1 witnesses (audit 55, fix/worm-rng-placement) ----
    // WRITTEN NOT RUN — code-only mode, no compiler invoked. Each pin
    // states the C# draw ledger it locks.

    #[test]
    fn the_budget_roll_draws_then_overrides_per_head_kind() {
        // `NPC.cs:51303-51342`: EVERY head in the list rolls
        // `Next(8, 13)` first (`:51310`); type 10 rolls AGAIN `Next(4, 7)`
        // (`:51313`), type 117 AGAIN `Next(3, 6)` (`:51341`), type 13
        // overrides with the constant count but CONSUMED the first draw
        // (`:51317`), type 7 keeps it. The pre-fix port dropped the
        // discarded draw for GiantWorm/Leech/EoW — a stream shift for
        // every later `UpdateNpcs` consumer.
        let world = World::new("t".into(), 64, 800); // air only: no scan draws
        for (kind, draws, lo, hi) in [
            (NpcKind::DevourerHead, 1usize, 8u32, 12u32),
            (NpcKind::GiantWormHead, 2, 4, 6),
            (NpcKind::LeechHead, 2, 3, 5),
            (NpcKind::EaterOfWorldsHead, 1, 65, 65),
        ] {
            let mut head = Npc::new(kind, 160.0, 160.0, 1, 0.0);
            head.hp = head.max_hp;
            let mut npcs = vec![head];
            let mut rng = UnifiedRandom::new(11);
            let mut oracle = UnifiedRandom::new(11);
            // W4-f4 b7: the Leech head's entry burst (site 50976) fires
            // at the latch BEFORE the budget roll — 20× type-5, 6 pool
            // internals each (50/50 box jitters, the velocity pair, the
            // frame row, the scale jitter), ZERO explicit draws.
            if kind == NpcKind::LeechHead {
                for _ in 0..20 {
                    let _ = oracle.next_max(50); // width 14+40-4
                    let _ = oracle.next_max(50); // height 14+40-4
                    let _ = oracle.next_range(-20, 21);
                    let _ = oracle.next_range(-20, 21);
                    let _ = oracle.next_max(3);
                    let _ = oracle.next_range(-20, 21);
                }
            }
            let mut expected = 0u32;
            for d in 0..draws {
                let v = if d == 0 {
                    oracle.next_range(8, 13) as u32
                } else {
                    match kind {
                        NpcKind::GiantWormHead => oracle.next_range(4, 7) as u32,
                        NpcKind::LeechHead => oracle.next_range(3, 6) as u32,
                        _ => unreachable!(),
                    }
                };
                expected = v;
            }
            // Type 13 overrides the (consumed) first draw with the constant
            // segment count — the oracle still drew it for stream parity.
            if kind == NpcKind::EaterOfWorldsHead {
                expected = 65;
            }
            let mut next_id = 1u32;
            // No player: the head machine is skipped, only the chain
            // init draws — the budget ledger is isolated. W4-f4: the EoW
            // head's spawn fade (`:52255-52263`, alpha 255 ctor row) still
            // runs its 2× type-14 burst — 12 pool-internal draws (6 per
            // NewDust on the empty scratch pool: the position pair, the
            // velocity pair, the frame row, the scale jitter; type 14
            // hits no per-type tweak). The links behind the opaque head
            // (alpha 255 >= 85) spawn nothing; the stationary head's
            // displacement is 0, so the alpha holds 255. W4-f4 b7: the
            // Leech head's entry burst (site 50976) runs at the latch —
            // 20× type-5, 6 internals each, ZERO explicit draws (the
            // oracle replayed it ahead of the budget roll above).
            update_worms_in(&world, None, &mut npcs, &mut rng, &mut next_id);
            if kind == NpcKind::EaterOfWorldsHead {
                for _ in 0..2 {
                    let _ = oracle.next_max(34); // width 38 - 4
                    let _ = oracle.next_max(34); // height 38 - 4
                    let _ = oracle.next_range(-20, 21);
                    let _ = oracle.next_range(-20, 21);
                    let _ = oracle.next_max(3);
                    let _ = oracle.next_range(-20, 21);
                }
                assert_eq!(npcs[0].alpha, 255, "the stationary head keeps its alpha");
                assert_eq!(npcs.len(), 67, "head + 65 bodies + tail");
                assert!(
                    npcs.iter().skip(1).all(|n| n.alpha == 255),
                    "the links behind the opaque head spawn nothing, alpha untouched"
                );
            }
            assert_eq!(npcs[0].worm_left, expected, "{kind:?} budget value");
            assert!(
                npcs[0].worm_left >= lo && npcs[0].worm_left <= hi,
                "{kind:?} budget range"
            );
            // Stream-position parity: the NEXT draw after the pass
            // equals the oracle's next draw after the same ledger.
            assert_eq!(
                rng.next(),
                oracle.next(),
                "{kind:?} post-spawn stream position"
            );
        }
    }

    #[test]
    fn the_destroyer_and_crawltipede_spawns_draw_nothing() {
        // The Destroyer rides `AI_037`'s own roll (outside the `:51303`
        // list — R55's wiring moved the family OUT of this pass entirely:
        // `is_worm()` is false, so the pass never touches it, never draws,
        // never grows a chain here). The crawltipede's fixed 30-link
        // spawn (`:51369-51392`) draws nothing either.
        let world = World::new("t".into(), 64, 800);
        {
            // The Destroyer: the pass skips it (not is_worm) — no budget
            // write, no chain, no draw (R55's byte-identical boundary).
            let mut head = Npc::new(NpcKind::TheDestroyer, 160.0, 160.0, 1, 0.0);
            head.hp = head.max_hp;
            let worm_left_before = head.worm_left;
            let mut npcs = vec![head];
            let mut rng = UnifiedRandom::new(11);
            let mut oracle = UnifiedRandom::new(11);
            let mut next_id = 1u32;
            update_worms_in(&world, None, &mut npcs, &mut rng, &mut next_id);
            assert_eq!(npcs.len(), 1, "the Destroyer family runs in update_destroyers");
            assert!(!npcs[0].worm_inited, "the pass never claims it");
            assert_eq!(npcs[0].worm_left, worm_left_before, "no budget write");
            assert_eq!(rng.next(), oracle.next(), "TheDestroyer no spawn draws");
        }
        {
            let mut head = Npc::new(NpcKind::SolarCrawltipedeHead, 160.0, 160.0, 1, 0.0);
            head.hp = head.max_hp;
            let mut npcs = vec![head];
            let mut rng = UnifiedRandom::new(11);
            let mut oracle = UnifiedRandom::new(11);
            let mut next_id = 1u32;
            update_worms_in(&world, None, &mut npcs, &mut rng, &mut next_id);
            assert_eq!(npcs[0].worm_left, 29, "SolarCrawltipedeHead budget");
            assert_eq!(rng.next(), oracle.next(), "SolarCrawltipedeHead no spawn draws");
        }
    }

    #[test]
    fn the_wyvern_family_never_enters_the_shared_worm_pass() {
        // N16: the wyvern family is NOT `is_worm()` — the shared pass
        // never claims it, never writes a budget, never grows a chain,
        // never draws (the R55 Destroyer precedent). The family's own
        // machine runs in `update_wyverns`.
        let world = World::new("t".into(), 64, 800);
        for kind in [
            NpcKind::WyvernHead,
            NpcKind::WyvernLegs,
            NpcKind::WyvernBody,
            NpcKind::WyvernBody2,
            NpcKind::WyvernBody3,
            NpcKind::WyvernTail,
        ] {
            assert!(!kind.is_worm(), "{kind:?} stays out of the worm pass");
            let mut head = Npc::new(kind, 160.0, 160.0, 1, 0.0);
            head.hp = head.max_hp;
            let mut npcs = vec![head];
            let mut rng = UnifiedRandom::new(11);
            let oracle = rng.clone();
            let mut next_id = 1u32;
            update_worms_in(&world, None, &mut npcs, &mut rng, &mut next_id);
            assert_eq!(npcs.len(), 1, "{kind:?} runs in update_wyverns");
            assert!(!npcs[0].worm_inited, "{kind:?} the pass never claims it");
            assert_eq!(rng, oracle, "{kind:?} no draws");
        }
    }

    #[test]
    fn the_wyvern_sim_pass_assembles_and_flies_the_chain() {
        // N16 through the WIRED sim pass (`update_wyverns`): the fresh
        // head assembles its 14 links on the first pass, the head flies
        // toward the player, the followers trail at the 42-px spacing —
        // and the `UpdateNpcs` stream is bit-identical across the whole
        // run (the module's RNG census, now over the live route).
        let mut app = crate::app::flow::front_flow_tests::flow_app(None, vec![], vec![]);
        let mut w = World::new("t".into(), 200, 200);
        w.world_surface = 50.0;
        app.world = w;
        let mut player = crate::player::Player::spawn(&app.world);
        player.x = 2400.0;
        player.y = 400.0;
        app.player = Some(player);
        let mut head = Npc::new(NpcKind::WyvernHead, 1600.0, 400.0, 1, 0.0);
        head.hp = head.max_hp;
        app.npcs.push(head);
        let rng = app.rngs.stream(RngKey::UpdateNpcs).clone();
        for _ in 0..60 {
            update_wyverns(&mut app);
        }
        assert_eq!(app.npcs.len(), 15, "head + 14 links");
        assert!(app.npcs.iter().all(|n| n.hp > 0));
        // The head moved toward the player (the +X aim).
        assert!(app.npcs[0].x > 1600.0, "the head flies +X");
        // The chain trails at the spacing (the 60 passes spread it).
        for i in 1..app.npcs.len() {
            let l = &app.npcs[i - 1];
            let f = &app.npcs[i];
            let d = ((l.x - f.x) * (l.x - f.x) + (l.y - f.y) * (l.y - f.y)).sqrt();
            assert!((d - 42.0).abs() < 0.5, "link {i} spacing {d}");
        }
        assert_eq!(
            *app.rngs.stream(RngKey::UpdateNpcs),
            rng,
            "the wyvern pass draws NOTHING on the UpdateNpcs stream"
        );
        // The shared worm pass leaves the family alone even in the App.
        update_worms(&mut app);
        assert_eq!(app.npcs.len(), 15);
    }

    #[test]
    fn the_child_spawns_bottom_at_the_parents_bottom() {
        // `NPC.cs:51347` + `NewNPC`'s `Bottom` setter (`:80770`,
        // `Entity.cs:128-131`): the child's BOTTOM sits at the parent's
        // bottom, X/Y int-truncated, X offset by the INT `width / 2`.
        // The Giant Worm head/body/tail are all 14x14, so the child's
        // top-left equals the parent's — the pre-fix port placed it one
        // child-height lower (`y + h`). The head sits at INTEGER coords:
        // the Bottom-placed child then exactly overlaps the head, so the
        // same-tick follower trail's delta is (0,0) and the spawn
        // coordinate survives the pass (a fractional head position makes
        // the trail's (len-lw)/len snap explode on the ~0-length delta —
        // the C#'s NaN corner, the port's len-guard — and moves the child).
        let world = World::new("t".into(), 64, 800);
        let mut head = Npc::new(NpcKind::GiantWormHead, 160.0, 160.0, 1, 0.0);
        head.hp = head.max_hp;
        let mut npcs = vec![head];
        let mut rng = UnifiedRandom::new(3);
        let mut next_id = 1u32;
        update_worms_in(&world, None, &mut npcs, &mut rng, &mut next_id);
        // The FIRST child (the chain grows head→bodies→tail in the same
        // pass; `last()` is the tail, not the head's direct child).
        let child = &npcs[1];
        assert_eq!(child.kind, NpcKind::GiantWormBody);
        // X = (int)(160 + 14/2) - 14/2 = 167 - 7 = 160
        assert_eq!(child.x, 160.0, "int-truncated bottom-centre X");
        // Y = (int)(160 + 14) - 14 = 174 - 14 = 160
        assert_eq!(child.y, 160.0, "child bottom at the parent bottom");
    }

    #[test]
    fn the_scan_draws_next100_per_overlapping_tile() {
        // `NPC.cs:51575-51597`: one `Next(100)` per OVERLAPPING tile in
        // scan order (X outer, Y inner), even when the crumble guards
        // fail. A 22x22 Devourer head at (160,160) over a solid floor at
        // row 10 overlaps tiles (10,10),(10,11),(11,10),(11,11) — four
        // draws per tick, THEN the head machine's own draws (none).
        let mut world = World::new("t".into(), 64, 800);
        for x in 0..64 {
            for y in 10..800 {
                let i = world.index(x, y);
                world.tiles[i] = tr_core::Tile {
                    kind: 1,
                    ..Default::default()
                };
                world.tiles[i].flags |= tr_core::tile::FLAG_ACTIVE;
            }
        }
        let mut head = Npc::new(NpcKind::DevourerHead, 160.0, 160.0, 1, 0.0);
        head.hp = head.max_hp;
        let mut npcs = vec![head];
        let mut rng = UnifiedRandom::new(5);
        let mut oracle = UnifiedRandom::new(5);
        let mut next_id = 1u32;
        // Two ticks: the init pass draws the budget (one `Next(8,13)`),
        // then each head tick draws 4 crumbles. The oracle replays the
        // same ledger.
        update_worms_in(&world, Some((160.0, 176.0)), &mut npcs, &mut rng, &mut next_id);
        let _ = oracle.next_range(8, 13); // the budget
        for _ in 0..4 {
            let _ = oracle.next_max(100);
        }
        assert_eq!(rng.next(), oracle.next(), "tick 1: budget + 4 crumbles");
        // Kill the chain so tick 2 runs only a fresh head's machine.
        for n in npcs.iter_mut() {
            n.hp = 0;
        }
        let mut head2 = Npc::new(NpcKind::DevourerHead, 160.0, 160.0, 1, 0.0);
        head2.hp = head2.max_hp;
        head2.worm_inited = true;
        head2.worm_id = 99;
        npcs.push(head2);
        update_worms_in(&world, Some((160.0, 176.0)), &mut npcs, &mut rng, &mut next_id);
        for _ in 0..4 {
            let _ = oracle.next_max(100);
        }
        assert_eq!(rng.next(), oracle.next(), "tick 2: 4 crumbles, no budget");
    }

