        let mut npcs2 = vec![deep, body];
        update_worms_in(&world, Some((160.0, 9616.0)), &mut npcs2, &mut rng, &mut next_id);
        assert!(npcs2.iter().all(|n| n.hp <= 0), "the whole chain despawns");
